insert into memories (kind,text,tags,provenance,entity_id) select 'budget','60 people ate 15 pizzas, GBP 142 from Slice & Co Catering (about 4 people per pizza, 9.50 per pizza plus delivery). Order 15 for 60 and almost nothing was left.',array['pizza','food','catering','per-head','quantity']::text[],'London AI Builders Meetup #12',(select id from entities where kind='supplier' and name='Slice & Co Catering') where not exists (select 1 from memories where text='60 people ate 15 pizzas, GBP 142 from Slice & Co Catering (about 4 people per pizza, 9.50 per pizza plus delivery). Order 15 for 60 and almost nothing was left.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Food cost came to about GBP 2.37 per head at the AI Builders meetup (pizza only). Adding coffee brought it to GBP 3.90 per head.',array['cost-per-head','food','meetup']::text[],'London AI Builders Meetup #12',null where not exists (select 1 from memories where text='Food cost came to about GBP 2.37 per head at the AI Builders meetup (pizza only). Adding coffee brought it to GBP 3.90 per head.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Bean There Coffee Cart charged GBP 2.80 per head for unlimited filter and tea at a 60 person evening meetup; about 70% of people took one.',array['coffee','drinks','per-head']::text[],'London AI Builders Meetup #12',(select id from entities where kind='supplier' and name='Bean There Coffee Cart') where not exists (select 1 from memories where text='Bean There Coffee Cart charged GBP 2.80 per head for unlimited filter and tea at a 60 person evening meetup; about 70% of people took one.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Always order 20% vegetarian and 10% vegan pizzas: 3 of 15 were vegetarian and all gone first.',array['pizza','dietary','vegetarian','vegan','food']::text[],'London AI Builders Meetup #12',(select id from entities where kind='supplier' and name='Slice & Co Catering') where not exists (select 1 from memories where text='Always order 20% vegetarian and 10% vegan pizzas: 3 of 15 were vegetarian and all gone first.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','120 hackathon attendees got 34 pizzas on Saturday night (GBP 323 from Slice & Co) plus breakfast pastries; roughly 3.5 people per pizza when people stay for hours.',array['pizza','food','hackathon','quantity']::text[],'Hack the Thames Weekend',(select id from entities where kind='supplier' and name='Slice & Co Catering') where not exists (select 1 from memories where text='120 hackathon attendees got 34 pizzas on Saturday night (GBP 323 from Slice & Co) plus breakfast pastries; roughly 3.5 people per pizza when people stay for hours.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Total spend for the 2 day hackathon was GBP 2,840 (GBP 23.70 per head), covered by Northwind Cloud GBP 1,500 and Fennel Ventures GBP 800.',array['cost-per-head','hackathon','budget','sponsor']::text[],'Hack the Thames Weekend',null where not exists (select 1 from memories where text='Total spend for the 2 day hackathon was GBP 2,840 (GBP 23.70 per head), covered by Northwind Cloud GBP 1,500 and Fennel Ventures GBP 800.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Crumbs Vegan Catering charged GBP 11 per head for a 35 person breakfast; minimum order 30 people and 7 days notice.',array['vegan','catering','breakfast','per-head']::text[],'Founders & Flat Whites Breakfast',(select id from entities where kind='supplier' and name='Crumbs Vegan Catering') where not exists (select 1 from memories where text='Crumbs Vegan Catering charged GBP 11 per head for a 35 person breakfast; minimum order 30 people and 7 days notice.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Drinks at the social cost GBP 6.50 per head via Pint Pot Drinks Co; expect 2.2 drinks per person across a 3 hour evening.',array['drinks','bar','per-head','social']::text[],'Data After Dark Social',(select id from entities where kind='supplier' and name='Pint Pot Drinks Co') where not exists (select 1 from memories where text='Drinks at the social cost GBP 6.50 per head via Pint Pot Drinks Co; expect 2.2 drinks per person across a 3 hour evening.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','A typical 60 person London evening meetup lands at GBP 6 to 9 per head all-in (food, drinks, print, AV) when the venue is free or cheap.',array['cost-per-head','meetup','budget']::text[],'London AI Builders Meetup #12',null where not exists (select 1 from memories where text='A typical 60 person London evening meetup lands at GBP 6 to 9 per head all-in (food, drinks, print, AV) when the venue is free or cheap.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Lumen AV Hire day rate is GBP 320 for a PA, two handheld mics and a lectern mic; book 10 days ahead.',array['av','mics','hire','budget']::text[],'Hack the Thames Weekend',(select id from entities where kind='supplier' and name='Lumen AV Hire') where not exists (select 1 from memories where text='Lumen AV Hire day rate is GBP 320 for a PA, two handheld mics and a lectern mic; book 10 days ahead.');
insert into memories (kind,text,tags,provenance,entity_id) select 'budget','Print for 60 attendees (badges, signage, 2 banners) cost GBP 64 from Thames Print Studio; 3 day turnaround.',array['print','badges','signage']::text[],'London AI Builders Meetup #12',(select id from entities where kind='supplier' and name='Thames Print Studio') where not exists (select 1 from memories where text='Print for 60 attendees (badges, signage, 2 banners) cost GBP 64 from Thames Print Studio; 3 day turnaround.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','The Shoreditch Loft is on the 3rd floor with no lift: tell guests, and plan two volunteers to help carry catering up. Hard curfew at 22:00.',array['venue','accessibility','curfew','shoreditch']::text[],'London AI Builders Meetup #12',(select id from entities where kind='venue' and name='The Shoreditch Loft') where not exists (select 1 from memories where text='The Shoreditch Loft is on the 3rd floor with no lift: tell guests, and plan two volunteers to help carry catering up. Hard curfew at 22:00.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','The Shoreditch Loft held 60 people comfortably standing but felt full at 75; the fire limit is 80.',array['venue','capacity','shoreditch']::text[],'Data After Dark Social',(select id from entities where kind='venue' and name='The Shoreditch Loft') where not exists (select 1 from memories where text='The Shoreditch Loft held 60 people comfortably standing but felt full at 75; the fire limit is 80.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','Canary Wharf Tech Hub is free for communities but security needs the final guest list 48 hours ahead; walk-ins are turned away.',array['venue','free','security','guest-list','canary wharf']::text[],'Hack the Thames Weekend',(select id from entities where kind='venue' and name='Canary Wharf Tech Hub') where not exists (select 1 from memories where text='Canary Wharf Tech Hub is free for communities but security needs the final guest list 48 hours ahead; walk-ins are turned away.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','Clerkenwell Coworking Studio has no kitchen, so catering must arrive ready to serve; bins are limited to two, bring extra bags.',array['venue','kitchen','catering','clerkenwell']::text[],'Founders & Flat Whites Breakfast',(select id from entities where kind='venue' and name='Clerkenwell Coworking Studio') where not exists (select 1 from memories where text='Clerkenwell Coworking Studio has no kitchen, so catering must arrive ready to serve; bins are limited to two, bring extra bags.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','King''s Cross Library Hall bans alcohol; the projector needs an HDMI-C adapter. Doors open 17:30, good for workshops.',array['venue','alcohol','projector','workshop','king''s cross']::text[],'Prompt Engineering Workshop Night',(select id from entities where kind='venue' and name='King''s Cross Library Hall') where not exists (select 1 from memories where text='King''s Cross Library Hall bans alcohol; the projector needs an HDMI-C adapter. Doors open 17:30, good for workshops.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','Brixton Warehouse Taproom is echoey: hire handheld mics or talks are unintelligible past row 4.',array['venue','av','acoustics','brixton']::text[],'Data After Dark Social',(select id from entities where kind='venue' and name='Brixton Warehouse Taproom') where not exists (select 1 from memories where text='Brixton Warehouse Taproom is echoey: hire handheld mics or talks are unintelligible past row 4.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','Old Street Basement Bar is free with a GBP 500 minimum bar spend; no AV, so bring your own screen and speaker.',array['venue','minimum spend','bar','old street']::text[],'Data After Dark Social',(select id from entities where kind='venue' and name='Old Street Basement Bar') where not exists (select 1 from memories where text='Old Street Basement Bar is free with a GBP 500 minimum bar spend; no AV, so bring your own screen and speaker.');
insert into memories (kind,text,tags,provenance,entity_id) select 'venue','Southbank Innovation Centre has excellent wifi and step-free access, but load-in is by side door only; GBP 900 hire.',array['venue','wifi','accessibility','southbank']::text[],'Hack the Thames Weekend',(select id from entities where kind='venue' and name='Southbank Innovation Centre') where not exists (select 1 from memories where text='Southbank Innovation Centre has excellent wifi and step-free access, but load-in is by side door only; GBP 900 hire.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Talks overran by 25 minutes at the AI Builders meetup because Q&A had no timekeeper. Assign a volunteer to hold a time card and cut Q&A hard.',array['run-sheet','overrun','talks','q&a','timing']::text[],'London AI Builders Meetup #12',null where not exists (select 1 from memories where text='Talks overran by 25 minutes at the AI Builders meetup because Q&A had no timekeeper. Assign a volunteer to hold a time card and cut Q&A hard.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Doors-to-first-talk gap of 30 minutes was right: 70% arrived in the last 10 minutes, so do not start on time at doors.',array['run-sheet','timing','doors','meetup']::text[],'London AI Builders Meetup #12',null where not exists (select 1 from memories where text='Doors-to-first-talk gap of 30 minutes was right: 70% arrived in the last 10 minutes, so do not start on time at doors.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Hackathon demos ran 40 minutes over because teams had 5 minutes instead of 3. Cap demos at 3 minutes with a visible timer.',array['run-sheet','overrun','demos','hackathon','timing']::text[],'Hack the Thames Weekend',null where not exists (select 1 from memories where text='Hackathon demos ran 40 minutes over because teams had 5 minutes instead of 3. Cap demos at 3 minutes with a visible timer.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Roughly 35% of RSVPs did not turn up at the free breakfast; for free events plan food for 65% of RSVPs, for GBP 5+ tickets for 85%.',array['no-show','rsvp','attendance','food']::text[],'Founders & Flat Whites Breakfast',null where not exists (select 1 from memories where text='Roughly 35% of RSVPs did not turn up at the free breakfast; for free events plan food for 65% of RSVPs, for GBP 5+ tickets for 85%.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Free-ticket meetups in London see about 40% no-shows when the event is on a Thursday; waitlist 20% over capacity.',array['no-show','rsvp','attendance','waitlist','meetup']::text[],'London AI Builders Meetup #12',null where not exists (select 1 from memories where text='Free-ticket meetups in London see about 40% no-shows when the event is on a Thursday; waitlist 20% over capacity.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Sponsors respond best to a one page deck with last event''s attendance and cost-per-head; Northwind Cloud replied within 2 days.',array['sponsor','outreach','deck']::text[],'Hack the Thames Weekend',(select id from entities where kind='sponsor' and name='Northwind Cloud') where not exists (select 1 from memories where text='Sponsors respond best to a one page deck with last event''s attendance and cost-per-head; Northwind Cloud replied within 2 days.');
insert into memories (kind,text,tags,provenance,entity_id) select 'lesson','Quill Analytics pays in kind (swag, one speaker) rather than cash; ask by email 3 weeks out.',array['sponsor','in-kind','swag','speaker']::text[],'Prompt Engineering Workshop Night',(select id from entities where kind='sponsor' and name='Quill Analytics') where not exists (select 1 from memories where text='Quill Analytics pays in kind (swag, one speaker) rather than cash; ask by email 3 weeks out.');
insert into memories (kind,text,tags,provenance,entity_id) select 'volunteer','Priya Nair is the most reliable door/check-in lead and has run shifts at three events; ask her first for a 60+ person event.',array['volunteer','check-in','rota']::text[],'Prompt Engineering Workshop Night',(select id from entities where kind='volunteer' and name='Priya Nair') where not exists (select 1 from memories where text='Priya Nair is the most reliable door/check-in lead and has run shifts at three events; ask her first for a 60+ person event.');
insert into memories (kind,text,tags,provenance,entity_id) select 'volunteer','Plan one volunteer per 20 attendees: 60 people needed 3 (door, greeter, AV/floor), 120 people needed 6 including a bar runner.',array['volunteer','rota','staffing','ratio']::text[],'Hack the Thames Weekend',null where not exists (select 1 from memories where text='Plan one volunteer per 20 attendees: 60 people needed 3 (door, greeter, AV/floor), 120 people needed 6 including a bar runner.');
insert into memories (kind,text,tags,provenance,entity_id) select 'voice','Organisers edited AI Builders copy to drop hype: prefers ''come build with us'' to ''revolutionary'', no emojis in headlines, always mention food is provided.',array['voice','tone','copy','linkedin']::text[],'London AI Builders Meetup #12',(select id from entities where kind='community' and name='London AI Builders') where not exists (select 1 from memories where text='Organisers edited AI Builders copy to drop hype: prefers ''come build with us'' to ''revolutionary'', no emojis in headlines, always mention food is provided.');
insert into memories (kind,text,tags,provenance,entity_id) select 'voice','Founders Circle posts are warm and understated: first names, short sentences, ends with ''Bring a friend who is building something.'' No hashtags.',array['voice','tone','copy','newsletter']::text[],'Founders & Flat Whites Breakfast',(select id from entities where kind='community' and name='London Founders Circle') where not exists (select 1 from memories where text='Founders Circle posts are warm and understated: first names, short sentences, ends with ''Bring a friend who is building something.'' No hashtags.');
insert into memories (kind,text,tags,provenance,entity_id) select 'voice','Hack London WhatsApp messages are punchy, lowercase-friendly, include the one-line address and ''doors 6pm sharp'' in the first line.',array['voice','whatsapp','copy']::text[],'Hack the Thames Weekend',(select id from entities where kind='community' and name='Hack London') where not exists (select 1 from memories where text='Hack London WhatsApp messages are punchy, lowercase-friendly, include the one-line address and ''doors 6pm sharp'' in the first line.');
